/**
 * @description: 获取汉语字符串的拼音
 * @param {string} word 要转换的汉语字符串
 * @param {CompleteOptions=} options 配置项
 * @return {string | string[] | AllData[]} options.type 为 string 时，返回字符串，中间用空格隔开；为 array 时，返回拼音字符串数组；为 all 时返回全部信息的数组
 */
function pinyin(word, options) {
    options = Object.assign(Object.assign({}, DEFAULT_OPTIONS), (options || {}));
    // 校验 word 类型是否正确
    const legal = validateType(word);
    if (!legal) {
        return word;
    }
    // 传入空字符串
    if (word === "") {
        return options.type === "array" || options.type === "all" ? [] : "";
    }
    if (options.surname === undefined) {
        if (options.mode === "surname") {
            options.surname = "all";
        }
        else {
            options.surname = "off";
        }
    }
    if (options.type === "all") {
        options.pattern = "pinyin";
    }
    if (options.pattern === "num") {
        options.toneType = "none";
    }
    if (options.removeNonZh) {
        options.nonZh = "removed";
    }
    const zhChars = splitString(word);
    let _list = Array(zhChars.length);
    let { list } = getPinyin(word, _list, options.surname, options.segmentit, options.traditional, zhChars);
    // 一和不变调处理
    list = middlewareToneSandhi(list, options.toneSandhi);
    // nonZh 参数及 removeNonZh 参数
    list = middleWareNonZh(list, options);
    // multiple 参数
    const multipleList = middlewareMultiple(word, options);
    if (multipleList) {
        list = multipleList;
    }
    // pattern 参数
    middlewarePattern(list, options);
    // toneType参数处理
    middlewareToneType(list, options);
    // v参数处理
    middlewareV(list, options);
    // type 参数处理
    return middlewareType(list, options, word);
}

function rememberRelativePath(file, relativePath) {
  try {
    Object.defineProperty(file, 'designRagRelativePath', {
      value: relativePath,
      configurable: true,
    });
  } catch {
    // Some browser File implementations are not extensible; the file name remains usable.
  }
  return file
}

function readFileEntry(entry, parentPath) {
  return new Promise((resolve, reject) => {
    entry.file(
      (file) => resolve([rememberRelativePath(file, `${parentPath}${file.name}`)]),
      reject,
    );
  })
}

function readDirectoryBatch(reader) {
  return new Promise((resolve, reject) => reader.readEntries(resolve, reject))
}

async function readDirectoryEntry(entry, parentPath) {
  const directoryPath = `${parentPath}${entry.name}/`;
  const reader = entry.createReader();
  const entries = [];
  while (true) {
    const batch = await readDirectoryBatch(reader);
    if (!batch.length) break
    entries.push(...batch);
  }
  const nested = await Promise.all(entries.map((child) => readEntry(child, directoryPath)));
  return nested.flat()
}

async function readEntry(entry, parentPath = '') {
  if (entry.isFile) return readFileEntry(entry, parentPath)
  if (entry.isDirectory) return readDirectoryEntry(entry, parentPath)
  return []
}

async function collectDroppedFiles(dataTransfer) {
  const items = [...(dataTransfer?.items || [])].filter((item) => item.kind === 'file');
  const entries = items.map((item) => item.webkitGetAsEntry?.()).filter(Boolean);
  if (!entries.length) return [...(dataTransfer?.files || [])]
  const nested = await Promise.all(entries.map((entry) => readEntry(entry)));
  return nested.flat()
}

function fileDisplayPath(file) {
  return file.designRagRelativePath || file.webkitRelativePath || file.name
}
function asciiKebab(value) {
  return String(value || '')
    .normalize('NFKC')
    .toLowerCase()
    .replace(/ü/g, 'v')
    .normalize('NFKD')
    .replace(/\p{M}/gu, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
}

/** Convert a display name into a stable ASCII identifier without changing the display name. */
function toProjectExternalKey(projectName) {
  const tokens = String(projectName || '').normalize('NFKC').match(/[\p{Script=Han}]+|[\p{L}\p{N}]+/gu) || [];
  return tokens
    .flatMap((token) => {
      if (/^[\p{Script=Han}]+$/u.test(token)) {
        return pinyin(token, { toneType: 'none', type: 'array' }).map(asciiKebab).filter(Boolean)
      }
      const ascii = asciiKebab(token);
      return ascii ? [ascii] : []
    })
    .join('-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
}

function inferProjectDefaults(files) {
  const rootFolders = new Set();
  for (const file of files || []) {
    const segments = fileDisplayPath(file).replace(/\\/g, '/').split('/').filter(Boolean);
    if (segments.length < 2) return null
    rootFolders.add(segments[0]);
  }
  if (rootFolders.size !== 1) return null
  const projectName = [...rootFolders][0];
  const projectExternalKey = toProjectExternalKey(projectName);
  return projectExternalKey ? { projectName, projectExternalKey } : null
}

